}

#include <stdio.h>
int loop_factorial(int n);
int tail_factorial(int n, int product);
int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1 || n < 0 || n > 7) return 1;
    int iterative = loop_factorial(n);
    int recursive = tail_factorial(n, 1);
    printf("loop=%d tail=%d\n", iterative, recursive);
    return 0;
}
int loop_factorial(int n) {
    int product = 1;
    for (int k = 2; k <= n; k++) product *= k;
    return product;
}
int tail_factorial(int n, int product) {
    if (n == 0) return product;
    return tail_factorial(n - 1, product * n);
}

#include <stdio.h>
void binary_digits(unsigned int value);
int main(void) {
    unsigned int value = 0u;
    if (scanf("%u", &value) != 1 || value > 255u) return 1;
    binary_digits(value);
    putchar('\n');
    return 0;
}
void binary_digits(unsigned int value) {
    unsigned int remainder = value % 2u;
    if (value >= 2u) binary_digits(value / 2u);
    putchar(remainder == 0u ? '0' : '1');
}

