#include <stdio.h>
#include "stay_support.h"
int read_nights(void) {
    int nights = 0;
    int status = scanf("%d", &nights);
    while (status != 1 || nights < 1 || nights > 3) {
        if (status == EOF) return -1;
        printf("retry\n");
        int ch = getchar();
        while (ch != EOF && ch != '\n') ch = getchar();
        if (ch == EOF) return -1;
        status = scanf("%d", &nights);
    }
    return nights;
}
double support_total(double rate, int nights) {
    double total = 0.0, factor = 1.0;
    for (int day = 0; day < nights; day++) {
        total += rate * factor;
        factor *= DAILY_FACTOR;
    }
    return total;
}

