int main(void) {
    int a = 4, b = 9;
    printf("outside-before=%d,%d\n", a, b);
    show_local_exchange(a, b);
    printf("outside-after=%d,%d\n", a, b);
    return 0;
}
void show_local_exchange(int first, int second) {
    printf("inside-before=%d,%d\n", first, second);
    int saved = first;
    first = second;
    second = saved;
    printf("inside-after=%d,%d\n", first, second);
}

#include <stdio.h>
void exchange_targets(int *first, int *second);
int main(void) {
    int a = 4, b = 9;
    exchange_targets(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}
void exchange_targets(int *first, int *second) {
    int from_second = *second;
    *second = *first;
    *first = from_second;
}

